RemoteConnectionAuthentication::RemoteConnectionAuthentication(PersistenceService& store,ConnectionProfiles& profiles):RemoteConnectionAuthentication(store,profiles,[](const auto& origin,const auto& credential,auto requirements,auto timeout,auto stop){return negotiate_remote_connection(origin,credential,std::move(requirements),timeout,RemoteTransportPolicy::verified_https,stop);}){}
RemoteConnectionAuthentication::RemoteConnectionAuthentication(PersistenceService& store,ConnectionProfiles& profiles,RemoteNegotiationExchange exchange,RemoteSessionReadExchange session_read,RemoteSessionCommandExchange create,RemoteSessionCommandExchange receipt,RemoteRunReadExchange run_read,RemoteRunCommandExchange run_submit,RemoteRunCommandExchange run_receipt):profiles_(profiles),credentials_(store,profiles),exchange_(std::move(exchange)),session_read_(std::move(session_read)),commands_(store),create_(std::move(create)),receipt_(std::move(receipt)),run_read_(std::move(run_read)),run_submit_(std::move(run_submit)),run_receipt_(std::move(run_receipt)){if(!run_submit_)run_submit_=[](const auto& o,const auto& c,const auto& g,const auto& scope,const auto& id,const auto& action,auto timeout,auto stop){return submit_remote_run(o,c,g,scope,id,action,timeout,RemoteTransportPolicy::verified_https,stop);};if(!run_receipt_)run_receipt_=[](const auto& o,const auto& c,const auto& g,const auto& scope,const auto& id,const auto& action,auto timeout,auto stop){return observe_remote_run_request(o,c,g,scope,id,action,timeout,RemoteTransportPolicy::verified_https,stop);};if(!run_read_)run_read_=[](const auto& origin,const auto& credential,const auto& grant,const auto& scope,const auto& session,const auto& run,auto timeout,auto stop){return read_remote_run(origin,credential,grant,scope,session,run,timeout,RemoteTransportPolicy::verified_https,stop);};if(!create_)create_=[](const auto& o,const auto& c,const auto& g,const auto& scope,const auto& id,const auto& title,auto timeout,auto stop){return create_remote_session(o,c,g,scope,id,title,timeout,RemoteTransportPolicy::verified_https,stop);};if(!receipt_)receipt_=[](const auto& o,const auto& c,const auto& g,const auto& scope,const auto& id,const auto& title,auto timeout,auto stop){return observe_remote_session_request(o,c,g,scope,id,title,timeout,RemoteTransportPolicy::verified_https,stop);};if(!exchange_)throw std::invalid_argument("Remote negotiation exchange is required");if(!session_read_)session_read_=[](const auto& origin,const auto& credential,const auto& grant,const auto& scope,const auto& session,auto timeout,auto stop){return read_remote_session(origin,credential,grant,scope,session,timeout,RemoteTransportPolicy::verified_https,stop);};}
RemoteCapturedScope RemoteConnectionAuthentication::open_scope(const std::string& id,std::int64_t revision,const std::string& scope){
    const auto catalog=profiles_.load();const auto found=std::find_if(catalog.profiles.begin(),catalog.profiles.end(),[&](const auto& profile){return profile.id==id;});if(found==catalog.profiles.end())throw NotFound("Remote connection profile not found");const auto profile=*found;if(profile.revision!=revision)throw Conflict("Remote connection profile revision changed");auto stored=credentials_.load(profile);validate_remote_session_scope(stored.grant,scope,now());auto admission=profiles_.admit_remote(profile);return {profile,std::move(stored.grant),scope,stored.revision};
}
RemoteStoredCredential RemoteConnectionAuthentication::load_scope(const RemoteCapturedScope& scope){
    auto stored=credentials_.load(scope.profile);if(stored.revision!=scope.credential_revision||encode_remote_negotiated_grant(stored.grant)!=encode_remote_negotiated_grant(scope.grant))throw Conflict("Captured remote authorization changed");validate_remote_session_scope(stored.grant,scope.scope_id,now());return stored;
}
void RemoteConnectionAuthentication::validate_scope(const RemoteCapturedScope& scope){(void)load_scope(scope);}
RemoteObservedSession RemoteConnectionAuthentication::read_session(const RemoteCapturedScope& scope,const std::string& session,std::chrono::milliseconds timeout,std::stop_token stop){
    if(session.empty()||session.size()>256||session=="."||session==".."||session.find_first_not_of("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_.-:")!=std::string::npos||timeout.count()<=0||timeout>std::chrono::minutes(2))throw std::invalid_argument("Invalid remote session observation request");
    auto stored=load_scope(scope);if(stop.stop_requested())throw TransportCancelled("Remote session observation cancelled before send");const auto result=session_read_(scope.profile.origin,stored.credential,stored.grant,scope.scope_id,session,timeout,stop);
    if(stop.stop_requested())throw TransportCancelled("Remote session observation cancelled");(void)load_scope(scope);if(result.id!=session||result.title.size()>4096||result.revision<1||result.revision>9007199254740991LL)throw TransportError("Invalid remote session observation");return result;
}
RemoteObservedRun RemoteConnectionAuthentication::read_run(const RemoteCapturedScope& scope,const std::string& session,const std::string& run,std::chrono::milliseconds timeout,std::stop_token stop){
    const auto identifier=[](const std::string& id){return !id.empty()&&id.size()<=256&&id!="."&&id!=".."&&id.find_first_not_of("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_.-:")==std::string::npos;};
    if(!identifier(session)||!identifier(run)||timeout.count()<=0||timeout>std::chrono::minutes(2))throw std::invalid_argument("Invalid remote run observation request");
    auto stored=load_scope(scope);validate_remote_run_scope(stored.grant,scope.scope_id,now());if(stop.stop_requested())throw TransportCancelled("Remote run observation cancelled before send");
    const auto result=run_read_(scope.profile.origin,stored.credential,stored.grant,scope.scope_id,session,run,timeout,stop);
    if(stop.stop_requested())throw TransportCancelled("Remote run observation cancelled");stored=load_scope(scope);validate_remote_run_scope(stored.grant,scope.scope_id,now());
    if(result.id!=run||result.session_id!=session||!identifier(result.root_id)||result.revision<1||result.revision>9007199254740991LL||(result.state!="queued"&&result.state!="running"&&result.state!="paused"&&result.state!="completed"&&result.state!="failed"&&result.state!="cancelled"))throw TransportError("Invalid remote run observation");
    return result;
}
bool RemoteConnectionAuthentication::commands_available(const RemoteCapturedScope& scope){const auto allowed=[&](bool run){try{if(run)validate_remote_run_submit_scope(scope.grant,scope.scope_id,now());else validate_remote_session_create_scope(scope.grant,scope.scope_id,now());return true;}catch(const RemoteNegotiationError&){return false;}catch(const TransportError&){return false;}catch(const std::invalid_argument&){return false;}};return allowed(false)||allowed(true);}
RemoteCommandRecord RemoteConnectionAuthentication::observe_command(const RemoteCapturedScope& scope,const std::string& id){auto stored=load_scope(scope);validate_remote_receipt_scope(stored.grant,scope.scope_id,now());const auto record=commands_.observe(id);if(std::holds_alternative<RemoteRunSubmitAction>(record.intent.action))validate_remote_run_receipt_scope(stored.grant,scope.scope_id,now());const auto& intent=record.intent;if(intent.connection_id!=scope.profile.id||intent.origin!=scope.profile.origin||intent.server_id!=scope.grant.server_id||intent.scope_id!=scope.scope_id)throw Conflict("Remote command belongs to another captured binding");(void)load_scope(scope);return record;}
RemoteCommandRecord RemoteConnectionAuthentication::create_session(const RemoteCapturedScope& scope,const std::string& id,const std::string& title,std::chrono::milliseconds timeout,std::stop_token stop){return send_command(scope,{id,scope.profile.id,scope.profile.origin,scope.grant.server_id,scope.scope_id,scope.profile.revision,scope.credential_revision,RemoteSessionCreateAction{title}},timeout,stop);}
RemoteCommandRecord RemoteConnectionAuthentication::submit_run(const RemoteCapturedScope& scope,const std::string& id,RemoteRunSubmitAction action,std::chrono::milliseconds timeout,std::stop_token stop){return send_command(scope,{id,scope.profile.id,scope.profile.origin,scope.grant.server_id,scope.scope_id,scope.profile.revision,scope.credential_revision,std::move(action)},timeout,stop);}
RemoteCommandRecord RemoteConnectionAuthentication::send_command(const RemoteCapturedScope& scope,const RemoteCommandIntent& intent,std::chrono::milliseconds timeout,std::stop_token stop){
 if(timeout.count()<=0||timeout>std::chrono::minutes(2))throw std::invalid_argument("Invalid remote command timeout");auto stored=load_scope(scope);const auto* run=std::get_if<RemoteRunSubmitAction>(&intent.action);if(run)validate_remote_run_submit_scope(stored.grant,scope.scope_id,now());else validate_remote_session_create_scope(stored.grant,scope.scope_id,now());if(stop.stop_requested())throw TransportCancelled("Remote command cancelled before preparation");
 auto record=commands_.prepare(intent);if(record.state!=RemoteCommandState::prepared)return record;if(!commands_.claim_send(intent))return commands_.observe(intent.request_id);
 // Unknown is durable before dispatch. No exception after this boundary can
 // authorize another send, even when the transport may have sent no bytes.
 try{(void)load_scope(scope);if(stop.stop_requested())throw TransportCancelled("Remote command cancelled before send");const auto reply=run?run_submit_(scope.profile.origin,stored.credential,stored.grant,scope.scope_id,intent.request_id,*run,timeout,stop):create_(scope.profile.origin,stored.credential,stored.grant,scope.scope_id,intent.request_id,std::get<RemoteSessionCreateAction>(intent.action).title,timeout,stop);if(stop.stop_requested())throw TransportCancelled("Remote command cancelled after send");(void)load_scope(scope);if(reply.resolution)return commands_.resolve(intent,*reply.resolution);}
 catch(const TransportError&){return commands_.observe(intent.request_id);}return commands_.observe(intent.request_id);
}
RemoteCommandRecord RemoteConnectionAuthentication::reconcile_command(const RemoteCapturedScope& scope,const std::string& id,std::chrono::milliseconds timeout,std::stop_token stop){
 if(timeout.count()<=0||timeout>std::chrono::minutes(2))throw std::invalid_argument("Invalid remote command timeout");auto stored=load_scope(scope);validate_remote_receipt_scope(stored.grant,scope.scope_id,now());const auto record=commands_.observe(id);const auto& intent=record.intent;if(intent.connection_id!=scope.profile.id||intent.origin!=scope.profile.origin||intent.server_id!=scope.grant.server_id||intent.scope_id!=scope.scope_id)throw Conflict("Remote command belongs to another captured binding");const auto* run=std::get_if<RemoteRunSubmitAction>(&intent.action);if(run)validate_remote_run_receipt_scope(stored.grant,scope.scope_id,now());if(record.state!=RemoteCommandState::unknown)return record;if(stop.stop_requested())throw TransportCancelled("Remote receipt observation cancelled before send");
 const auto reply=run?run_receipt_(scope.profile.origin,stored.credential,stored.grant,scope.scope_id,id,*run,timeout,stop):receipt_(scope.profile.origin,stored.credential,stored.grant,scope.scope_id,id,std::get<RemoteSessionCreateAction>(intent.action).title,timeout,stop);if(stop.stop_requested())throw TransportCancelled("Remote receipt observation cancelled");(void)load_scope(scope);if(reply.resolution)return commands_.resolve(intent,*reply.resolution);return commands_.observe(id);
}
RemoteAuthenticationStatus RemoteConnectionAuthentication::inspect(const std::string& id,std::int64_t revision){
    const auto catalog=profiles_.load();const auto found=std::find_if(catalog.profiles.begin(),catalog.profiles.end(),[&](const auto& profile){return profile.id==id;});if(found==catalog.profiles.end())throw NotFound("Remote connection profile not found");const auto profile=*found;if(profile.revision!=revision)throw Conflict("Remote connection profile revision changed");
    RemoteAuthenticationStatus status;status.connection_id=profile.id;status.profile_revision=profile.revision;std::optional<RemoteStoredCredential> stored;
    try{stored=credentials_.previous(profile);}catch(const NotFound&){}
    auto admission=profiles_.admit_remote(profile);if(!stored)return status;status.credential_revision=stored->revision;
    if(stored->profile.origin!=profile.origin||stored->profile.revision!=profile.revision){status.state="stale_profile";return status;}
    status.state=stored->grant.expires_at<=now()?"expired":"stored";status.server_id=stored->grant.server_id;status.protocol_version=stored->grant.protocol_version;status.expires_at=stored->grant.expires_at;if(status.state=="stored")status.authorized_scopes=stored->grant.authorized_scopes;return status;
}
RemoteAuthenticationReceipt RemoteConnectionAuthentication::authenticate(const std::string& id,std::int64_t revision,std::int64_t credential_revision,const SecretBytes& credential,std::chrono::milliseconds timeout,std::stop_token stop){
    if(credential_revision<0||credential_revision==INT64_MAX||timeout.count()<=0||timeout>std::chrono::minutes(2)||credential.view().empty()||credential.view().size()>8192)throw std::invalid_argument("Invalid remote authentication request");for(const auto c:credential.view())if(c<33||c>126)throw std::invalid_argument("Invalid remote credential");
    const auto catalog=profiles_.load();const auto found=std::find_if(catalog.profiles.begin(),catalog.profiles.end(),[&](const auto& profile){return profile.id==id;});if(found==catalog.profiles.end())throw NotFound("Remote connection profile not found");const auto profile=*found;if(profile.revision!=revision)throw Conflict("Remote connection profile revision changed");{auto admission=profiles_.admit_remote(profile);}
    RemoteNegotiationRequirements requirements;requirements.now_unix_seconds=now();requirements.required_capabilities={{"sessions",1},{"runs",1},{"events",1},{"receipts",1}};
    try{auto previous=credentials_.previous(profile);if(previous.revision!=credential_revision)throw Conflict("Remote credential revision changed");if(previous.profile.origin==profile.origin)requirements.expected_server_id=previous.grant.server_id;}
    catch(const NotFound&){if(credential_revision!=0)throw;}
    if(stop.stop_requested())throw TransportCancelled("Remote authentication cancelled before negotiation");
    const auto negotiated=exchange_(profile.origin,credential,requirements,timeout,stop);if(stop.stop_requested())throw TransportCancelled("Remote authentication cancelled before publication");requirements.now_unix_seconds=now();const auto grant=validate_remote_negotiation(encode_remote_negotiated_grant(negotiated),requirements);
    const auto saved=credentials_.save(profile,grant,credential,credential_revision,requirements.now_unix_seconds);return {profile.id,grant.server_id,profile.revision,saved.revision,grant.protocol_version,grant.expires_at};
}
